120	impl ParserRef<'_> {
121	    /// Whether the message's flags hold any of the `llhttp_flags` bits of `flags`.
122	    fn flagged(self, flags: sys::llhttp_flags) -> bool {
123	        u32::from(self.flags_raw()) & flags != 0
124	    }
125	
126	    /// Whether the parser is lenient with any of the `llhttp_lenient_flags` bits of
127	    /// `flags`.
128	    fn lenient(self, flags: sys::llhttp_lenient_flags) -> bool {
129	        u32::from(self.lenient_flags_raw()) & flags != 0
130	    }
131	
132	    /// Whether the message being read is a request: its parser reads requests, or one of
133	    /// both kinds settled on a request.
134	    fn is_request(self) -> bool {
135	        self.parser_type() == Ok(ParserType::Request)
136	    }
137	
138	    /// Whether the message being read is a response.
139	    fn is_response(self) -> bool {
140	        self.parser_type() == Ok(ParserType::Response)
141	    }
142	
143	    /// Whether the message's body ends only with the input, so that the parser completes it
144	    /// once [`finish`](ParserMut::finish) says the input has ended: a response that has a
145	    /// body (not a `1xx`, `204` or `304` one, nor one to a `HEAD` request) but no
146	    /// `Content-Length` and no chunked `Transfer-Encoding`, or whose `Transfer-Encoding` does
147	    /// not end with `chunked`. A request never does.
148	    ///
149	    /// ```
150	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
151	    ///
152	    /// let mut parser = Parser::new();
153	    /// parser.as_mut().init(ParserType::Response, None);
154	    /// parser.as_mut().execute(b"HTTP/1.1 200 OK\r\n\r\n").unwrap();
155	    /// assert!(parser.as_ref().message_needs_eof());
156	    ///
157	    /// parser.as_mut().init(ParserType::Response, None);
158	    /// parser
159	    ///     .as_mut()
160	    ///     .execute(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\n")
161	    ///     .unwrap();
162	    /// assert!(!parser.as_ref().message_needs_eof());
163	    /// ```
164	    ///
165	    /// Replaces `fn::llhttp_message_needs_eof`
166	    #[doc(alias = "llhttp_message_needs_eof")]
167	    #[must_use]
168	    pub fn message_needs_eof(&self) -> bool {
169	        if self.is_request() {
170	            return false;
171	        }
172	        // RFC 2616, 4.4.
173	        let status = self.status_code();
174	        if status / 100 == 1 || status == 204 || status == 304 || self.flagged(sys::F_SKIPBODY) {
175	            return false;
176	        }
177	        // RFC 7230, 3.3.3: see `after_headers_complete`.
178	        if self.flagged(sys::F_TRANSFER_ENCODING) && !self.flagged(sys::F_CHUNKED) {
179	            return true;
180	        }
181	        !self.flagged(sys::F_CHUNKED | sys::F_CONTENT_LENGTH)
182	    }
183	
184	    /// Whether another message may follow the one parsed on the same connection: an
185	    /// HTTP/1.1 one without `Connection: close`, or an earlier one with `Connection:
186	    /// keep-alive`, whose body does not end with the input
187	    /// ([`message_needs_eof`](Self::message_needs_eof)).
188	    ///
189	    /// The version is HTTP/1.1 or later only when its major and minor are both above zero, as
190	    /// llhttp reads it, so an `HTTP/2.0` message is read as an earlier one.
191	    ///
192	    /// ```
193	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
194	    ///
195	    /// let mut parser = Parser::new();
196	    /// parser.as_mut().init(ParserType::Response, None);
197	    /// parser
198	    ///     .as_mut()
199	    ///     .execute(b"HTTP/1.1 204 No Content\r\n\r\n")
200	    ///     .unwrap();
201	    /// assert!(parser.as_ref().should_keep_alive());
202	    ///
203	    /// parser.as_mut().init(ParserType::Response, None);
204	    /// parser
205	    ///     .as_mut()
206	    ///     .execute(b"HTTP/1.0 204 No Content\r\n\r\n")
207	    ///     .unwrap();
208	    /// assert!(!parser.as_ref().should_keep_alive());
209	    /// ```
210	    ///
211	    /// Replaces `fn::llhttp_should_keep_alive`
212	    #[doc(alias = "llhttp_should_keep_alive")]
213	    #[must_use]
214	    pub fn should_keep_alive(&self) -> bool {
215	        if self.http_major() > 0 && self.http_minor() > 0 {
216	            // HTTP/1.1.
217	            if self.flagged(sys::F_CONNECTION_CLOSE) {
218	                return false;
219	            }
220	        } else if !self.flagged(sys::F_CONNECTION_KEEP_ALIVE) {
221	            // HTTP/1.0 or earlier.
222	            return false;
223	        }
224	        !self.message_needs_eof()
225	    }
226	
227	    /// How the message's body follows its headers, as llhttp's generated parser asks once
228	    /// `on_headers_complete` has run: none, another protocol, chunks, `Content-Length` bytes
229	    /// or the rest of the input, each [`Body`] as it describes. A response's status decides
230	    /// first (RFC 2616, 4.4), then the response to a `HEAD` request, a chunked
231	    /// `Transfer-Encoding`, which overrides a `Content-Length`, any other
232	    /// `Transfer-Encoding`, and the `Content-Length`.
233	    ///
234	    /// # Errors
235	    ///
236	    /// [`InvalidTransferEncoding`] for a request whose `Transfer-Encoding` does not end with
237	    /// `chunked`, unless the parser is lenient with a chunked length or with the
238	    /// `Transfer-Encoding` (RFC 7230, 3.3.3).
239	    ///
240	    /// ```
241	    /// use libgit2_crustify::libgit2::deps::llhttp::http::Body;
242	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
243	    ///
244	    /// let mut parser = Parser::new();
245	    /// parser.as_mut().init(ParserType::Response, None);
246	    /// parser
247	    ///     .as_mut()
248	    ///     .execute(b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n")
249	    ///     .unwrap();
250	    /// assert_eq!(parser.as_ref().after_headers_complete(), Ok(Body::Chunked));
251	    /// ```
252	    ///
253	    /// Replaces `fn::llhttp__after_headers_complete`
254	    #[doc(alias = "llhttp__after_headers_complete")]
255	    pub fn after_headers_complete(&self) -> Result<Body, InvalidTransferEncoding> {
256	        let status = self.status_code();
257	        let response = self.is_response();
258	        let chunked = self.flagged(sys::F_CHUNKED);
259	        let skip_body = self.flagged(sys::F_SKIPBODY);
260	        let has_body = chunked || self.content_length() > 0;
261	        if (self.upgrade() && (self.method() == Ok(Method::Connect) || skip_body || !has_body))
262	            // RFC 2616, 4.4: 1xx, as `Continue`.
263	            || (response && status == 101)
264	        {
265	            // The rest of the message is in another protocol.
266	            return Ok(Body::Upgrade);
267	        }
268	        if response && status == 100 {
269	            // No body: the message is complete.
270	            return Ok(Body::Empty);
271	        }
272	        // RFC 2616, 4.4: the response to a `HEAD` request, `Processing`, `Early Hints`,
273	        // `No Content` and `Not Modified`.
274	        if skip_body || (response && matches!(status, 102 | 103 | 204 | 304)) {
275	            Ok(Body::Empty)
276	        } else if chunked {
277	            // A chunked encoding overrides the `Content-Length`.
278	            Ok(Body::Chunked)
279	        } else if self.flagged(sys::F_TRANSFER_ENCODING) {
280	            // RFC 7230, 3.3.3: a request's body length cannot be told when its last coding is
281	            // not `chunked`, which the server answers with a 400; a response's body is read
282	            // until the connection closes.
283	            if self.is_request()
284	                && !self.lenient(sys::LENIENT_CHUNKED_LENGTH)
285	                && !self.lenient(sys::LENIENT_TRANSFER_ENCODING)
286	            {
287	                Err(InvalidTransferEncoding)
288	            } else {
289	                Ok(Body::UntilEof)
290	            }
291	        } else if !self.flagged(sys::F_CONTENT_LENGTH) {
292	            if self.message_needs_eof() {
293	                Ok(Body::UntilEof)
294	            } else {
295	                // A length of 0 is assumed: the next message is read.
296	                Ok(Body::Empty)
297	            }
298	        } else if self.content_length() == 0 {
299	            Ok(Body::Empty)
300	        } else {
301	            Ok(Body::Length)
302	        }
303	    }
304	}
