306	impl ParserMut<'_> {
307	    /// Sets whether the message upgrades the connection, [`upgrade`](ParserRef::upgrade),
308	    /// as llhttp's generated parser asks once the headers are read and before
309	    /// `on_headers_complete` runs, so that the callback sees it. A message with both
310	    /// `Upgrade` and `Connection: upgrade` upgrades when it is a request, or a `101
311	    /// Switching Protocols` response: for any other response the headers only announce
312	    /// support. Any other message upgrades when it is a `CONNECT` request.
313	    ///
314	    /// ```
315	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
316	    ///
317	    /// let mut parser = Parser::new();
318	    /// parser.as_mut().init(ParserType::Response, None);
319	    /// parser
320	    ///     .as_mut()
321	    ///     .execute(b"HTTP/1.1 200 OK\r\nConnection: upgrade\r\nUpgrade: h2c\r\n\r\n")
322	    ///     .unwrap();
323	    /// assert!(!parser.as_ref().upgrade());
324	    /// parser.as_mut().set_upgrade(true);
325	    /// parser.as_mut().before_headers_complete();
326	    /// assert!(!parser.as_ref().upgrade());
327	    /// ```
328	    ///
329	    /// Replaces `fn::llhttp__before_headers_complete`
330	    #[doc(alias = "llhttp__before_headers_complete")]
331	    pub fn before_headers_complete(&mut self) {
332	        let upgrade = {
333	            let parser = self.as_ref();
334	            if parser.flagged(sys::F_UPGRADE) && parser.flagged(sys::F_CONNECTION_UPGRADE) {
335	                parser.is_request() || parser.status_code() == 101
336	            } else {
337	                parser.method() == Ok(Method::Connect)
338	            }
339	        };
340	        self.set_upgrade(upgrade);
341	    }
342	
343	    /// Ends the message, as llhttp's generated parser does once `on_message_complete` has
344	    /// run: returns whether another message may follow on the same connection
345	    /// ([`should_keep_alive`](ParserRef::should_keep_alive)), then marks the parser safe to
346	    /// finish, `HTTP_FINISH_SAFE`, and clears the message's flags for the next.
347	    ///
348	    /// ```
349	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
350	    ///
351	    /// let mut parser = Parser::new();
352	    /// parser.as_mut().init(ParserType::Response, None);
353	    /// parser
354	    ///     .as_mut()
355	    ///     .execute(b"HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Length: 1\r\n\r\n")
356	    ///     .unwrap();
357	    /// assert_ne!(parser.as_ref().flags_raw(), 0);
358	    /// assert!(!parser.as_mut().after_message_complete());
359	    /// assert_eq!(parser.as_ref().flags_raw(), 0);
360	    /// ```
361	    ///
362	    /// Replaces `fn::llhttp__after_message_complete`
363	    #[doc(alias = "llhttp__after_message_complete")]
364	    pub fn after_message_complete(&mut self) -> bool {
365	        let keep_alive = self.as_ref().should_keep_alive();
366	        self.set_finish_raw(FINISH_SAFE);
367	        self.set_flags_raw(0);
368	        keep_alive
369	    }
370	}
371	
372	/// The `int` `llhttp__after_headers_complete` returns for `outcome`, which llhttp's generated
373	/// parser switches on.
374	#[cfg_attr(
375	    not(any(test, feature = "ffi-export-deps-llhttp-http-c")),
376	    expect(
377	        dead_code,
378	        reason = "only the export feature's gateway hands C the code"
379	    )
380	)]
381	const fn headers_code(outcome: Result<Body, InvalidTransferEncoding>) -> core::ffi::c_int {
382	    match outcome {
383	        Ok(Body::Empty) => 0,
384	        Ok(Body::Upgrade) => 1,
385	        Ok(Body::Chunked) => 2,
386	        Ok(Body::Length) => 3,
387	        Ok(Body::UntilEof) => 4,
388	        Err(InvalidTransferEncoding) => 5,
389	    }
390	}
391	
392	#[cfg(test)]
393	mod unit_priv {
394	    use super::{Body, InvalidTransferEncoding, headers_code};
395	
396	    /// Each outcome is the code `llhttp.c`'s `switch` goes on from: `1` to complete the
397	    /// message for another protocol, `2` to a chunk's size, `3` to a `Content-Length` body,
398	    /// `4` to a body until the input's end, `5` to `HPE_INVALID_TRANSFER_ENCODING`, and any
399	    /// other, `0`, to complete the message.
400	    #[test]
401	    fn headers_code_is_the_code_the_parser_switches_on() {
402	        assert_eq!(headers_code(Ok(Body::Empty)), 0);
403	        assert_eq!(headers_code(Ok(Body::Upgrade)), 1);
404	        assert_eq!(headers_code(Ok(Body::Chunked)), 2);
405	        assert_eq!(headers_code(Ok(Body::Length)), 3);
406	        assert_eq!(headers_code(Ok(Body::UntilEof)), 4);
407	        assert_eq!(headers_code(Err(InvalidTransferEncoding)), 5);
408	    }
409	
410	    /// `FINISH_SAFE` is `HTTP_FINISH_SAFE`'s byte.
411	    #[test]
412	    fn finish_safe_is_http_finish_safe() {
413	        assert_eq!(u32::from(super::FINISH_SAFE), super::sys::HTTP_FINISH_SAFE);
414	    }
415	}
