417	// The feature's `cfg` is the attribute right above the module, as build.rs's `gateway_lines`
418	// reads a gateway's feature from the lines before it.
419	#[expect(
420	    unsafe_code,
421	    reason = "exports http.c's functions the remaining C calls, adopting the parser C passes"
422	)]
423	#[cfg(feature = "ffi-export-deps-llhttp-http-c")]
424	mod ffi_export {
425	    use core::ffi::{c_int, c_uchar};
426	
427	    use ffibox::callback::barrier;
428	    use ffibox::{CMutSeam, CRefSeam};
429	
430	    use super::headers_code;
431	    use crate::libgit2::deps::llhttp::llhttp::{ParserMut, ParserRef};
432	    use crate::sys::libgit2 as sys;
433	
434	    // `llhttp_should_keep_alive` has its raw binding's type: the array's elements coerce to
435	    // one function pointer type only when their signatures agree.
436	    const _: () = {
437	        let _ = [sys::llhttp_should_keep_alive, llhttp_should_keep_alive];
438	    };
439	
440	    /// A hook's type as `llhttp.c` declares the three it calls (`c/deps/llhttp/llhttp.c`,
441	    /// lines 711, 753 and 761), `int llhttp__<hook>(llhttp__internal_t* s, const unsigned
442	    /// char* p, const unsigned char* endp)`: no header declares them, so they have no raw
443	    /// binding, and each export is checked against this type instead. http.c defines them over
444	    /// `llhttp_t` and `const char*`, the same types to the ABI.
445	    type Hook =
446	        unsafe extern "C" fn(*mut sys::llhttp__internal_t, *const c_uchar, *const c_uchar) -> c_int;
447	
448	    const _: () = {
449	        let _: Hook = llhttp__before_headers_complete;
450	        let _: Hook = llhttp__after_headers_complete;
451	        let _: Hook = llhttp__after_message_complete;
452	    };
453	
454	    /// The exclusive handle of the parser C passes a hook.
455	    ///
456	    /// # Safety
457	    ///
458	    /// `parser` is NULL, or points at a live `llhttp_t` which nothing else accesses while the
459	    /// handle lives, and whose `reason` is NULL or one of llhttp's literals: the parser
460	    /// `llhttp.c`'s generated parser passes a hook from inside its parse.
461	    unsafe fn parser_mut<'a>(parser: *mut sys::llhttp__internal_t) -> Option<ParserMut<'a>> {
462	        // SAFETY: the caller guarantees that `parser` is NULL or a live parser, exclusively
463	        // held for the handle's lifetime, which is the export's call: each export makes its
464	        // one operation with the handle and drops it before returning. Its `reason` is NULL or
465	        // one of llhttp's literals, which live as long as the program. The hooks read and
466	        // write only the parser's integers, never its `data` or `settings`, whose contracts
467	        // are therefore not relied on.
468	        unsafe { ParserMut::from_ptr(parser) }
469	    }
470	
471	    /// `llhttp__before_headers_complete`: [`ParserMut::before_headers_complete`], returning
472	    /// `0`; `p` and `endp` are not read. It cannot fail, so a panic aborts, as a NULL parser,
473	    /// which C would follow, does.
474	    ///
475	    /// # Safety
476	    ///
477	    /// `parser` as `parser_mut` requires.
478	    #[unsafe(no_mangle)]
