143	   143	    /// Whether the message's body ends only with the input, so that the parser completes it
144	   144	    /// once [`finish`](ParserMut::finish) says the input has ended: a response that has a
145	   145	    /// body (not a `1xx`, `204` or `304` one, nor one to a `HEAD` request) but no
146	   146	    /// `Content-Length` and no chunked `Transfer-Encoding`, or whose `Transfer-Encoding` does
147	   147	    /// not end with `chunked`. A request never does.
148	   148	    ///
149	   149	    /// ```
150	   150	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
151	   151	    ///
152	   152	    /// let mut parser = Parser::new();
153	   153	    /// parser.as_mut().init(ParserType::Response, None);
154	   154	    /// parser.as_mut().execute(b"HTTP/1.1 200 OK\r\n\r\n").unwrap();
155	   155	    /// assert!(parser.as_ref().message_needs_eof());
156	   156	    ///
157	   157	    /// parser.as_mut().init(ParserType::Response, None);
158	   158	    /// parser
159	   159	    ///     .as_mut()
160	   160	    ///     .execute(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\n")
161	   161	    ///     .unwrap();
162	   162	    /// assert!(!parser.as_ref().message_needs_eof());
163	   163	    /// ```
164	   164	    ///
165	   165	    /// Replaces `fn::llhttp_message_needs_eof`
166	   166	    #[doc(alias = "llhttp_message_needs_eof")]
167	   167	    #[must_use]
168	   168	    pub fn message_needs_eof(&self) -> bool {
169	   169	        if self.is_request() {
170	   170	            return false;
171	   171	        }
172	   172	        // RFC 2616, 4.4.
173	   173	        let status = self.status_code();
174	   174	        if status / 100 == 1 || status == 204 || status == 304 || self.flagged(sys::F_SKIPBODY) {
175	   175	            return false;
176	   176	        }
177	   177	        // RFC 7230, 3.3.3: see `after_headers_complete`.
178	   178	        if self.flagged(sys::F_TRANSFER_ENCODING) && !self.flagged(sys::F_CHUNKED) {
179	   179	            return true;
180	   180	        }
181	   181	        !self.flagged(sys::F_CHUNKED | sys::F_CONTENT_LENGTH)
182	   182	    }
