241	   241	    /// use libgit2_crustify::libgit2::deps::llhttp::http::Body;
242	   242	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
243	   243	    ///
244	   244	    /// let mut parser = Parser::new();
245	   245	    /// parser.as_mut().init(ParserType::Response, None);
246	   246	    /// parser
247	   247	    ///     .as_mut()
