255	   255	    pub fn after_headers_complete(&self) -> Result<Body, InvalidTransferEncoding> {
256	   256	        let status = self.status_code();
257	   257	        let response = self.is_response();
258	   258	        let chunked = self.flagged(sys::F_CHUNKED);
259	   259	        let skip_body = self.flagged(sys::F_SKIPBODY);
260	   260	        let has_body = chunked || self.content_length() > 0;
261	   261	        if (self.upgrade() && (self.method() == Ok(Method::Connect) || skip_body || !has_body))
262	   262	            // RFC 2616, 4.4: 1xx, as `Continue`.
263	   263	            || (response && status == 101)
264	   264	        {
265	   265	            // The rest of the message is in another protocol.
266	   266	            return Ok(Body::Upgrade);
267	   267	        }
268	   268	        if response && status == 100 {
269	   269	            // No body: the message is complete.
270	   270	            return Ok(Body::Empty);
271	   271	        }
272	   272	        // RFC 2616, 4.4: the response to a `HEAD` request, `Processing`, `Early Hints`,
273	   273	        // `No Content` and `Not Modified`.
274	   274	        if skip_body || (response && matches!(status, 102 | 103 | 204 | 304)) {
275	   275	            Ok(Body::Empty)
276	   276	        } else if chunked {
277	   277	            // A chunked encoding overrides the `Content-Length`.
278	   278	            Ok(Body::Chunked)
279	   279	        } else if self.flagged(sys::F_TRANSFER_ENCODING) {
280	   280	            // RFC 7230, 3.3.3: a request's body length cannot be told when its last coding is
281	   281	            // not `chunked`, which the server answers with a 400; a response's body is read
282	   282	            // until the connection closes.
283	   283	            if self.is_request()
284	   284	                && !self.lenient(sys::LENIENT_CHUNKED_LENGTH)
285	   285	                && !self.lenient(sys::LENIENT_TRANSFER_ENCODING)
286	   286	            {
287	   287	                Err(InvalidTransferEncoding)
288	   288	            } else {
289	   289	                Ok(Body::UntilEof)
290	   290	            }
291	   291	        } else if !self.flagged(sys::F_CONTENT_LENGTH) {
292	   292	            if self.message_needs_eof() {
293	   293	                Ok(Body::UntilEof)
294	   294	            } else {
295	   295	                // A length of 0 is assumed: the next message is read.
296	   296	                Ok(Body::Empty)
297	   297	            }
298	   298	        } else if self.content_length() == 0 {
299	   299	            Ok(Body::Empty)
300	   300	        } else {
301	   301	            Ok(Body::Length)
302	   302	        }
303	   303	    }
304	   304	}
