321	   321	    ///     .execute(b"HTTP/1.1 200 OK\r\nConnection: upgrade\r\nUpgrade: h2c\r\n\r\n")
322	   322	    ///     .unwrap();
323	   323	    /// assert!(!parser.as_ref().upgrade());
324	   324	    /// parser.as_mut().set_upgrade(true);
325	   325	    /// parser.as_mut().before_headers_complete();
326	   326	    /// assert!(!parser.as_ref().upgrade());
327	   327	    /// ```
