329	   329	    /// Replaces `fn::llhttp__before_headers_complete`
330	   330	    #[doc(alias = "llhttp__before_headers_complete")]
331	   331	    pub fn before_headers_complete(&mut self) {
332	   332	        let upgrade = {
333	   333	            let parser = self.as_ref();
334	   334	            if parser.flagged(sys::F_UPGRADE) && parser.flagged(sys::F_CONNECTION_UPGRADE) {
335	   335	                parser.is_request() || parser.status_code() == 101
336	   336	            } else {
337	   337	                parser.method() == Ok(Method::Connect)
338	   338	            }
339	   339	        };
340	   340	        self.set_upgrade(upgrade);
341	   341	    }
