352	   352	    /// parser.as_mut().init(ParserType::Response, None);
353	   353	    /// parser
354	   354	    ///     .as_mut()
355	   355	    ///     .execute(b"HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Length: 1\r\n\r\n")
356	   356	    ///     .unwrap();
357	   357	    /// assert_ne!(parser.as_ref().flags_raw(), 0);
358	   358	    /// assert!(!parser.as_mut().after_message_complete());
359	   359	    /// assert_eq!(parser.as_ref().flags_raw(), 0);
360	   360	    /// ```
