381	   381	const fn headers_code(outcome: Result<Body, InvalidTransferEncoding>) -> core::ffi::c_int {
382	   382	    match outcome {
383	   383	        Ok(Body::Empty) => 0,
384	   384	        Ok(Body::Upgrade) => 1,
385	   385	        Ok(Body::Chunked) => 2,
386	   386	        Ok(Body::Length) => 3,
387	   387	        Ok(Body::UntilEof) => 4,
388	   388	        Err(InvalidTransferEncoding) => 5,
389	   389	    }
390	   390	}
