441	   441	    /// lines 711, 753 and 761), `int llhttp__<hook>(llhttp__internal_t* s, const unsigned
442	   442	    /// char* p, const unsigned char* endp)`: no header declares them, so they have no raw
443	   443	    /// binding, and each export is checked against this type instead. http.c defines them over
444	   444	    /// `llhttp_t` and `const char*`, the same types to the ABI.
445	   445	    type Hook =
