459	   459	    /// handle lives, and whose `reason` is NULL or one of llhttp's literals: the parser
460	   460	    /// `llhttp.c`'s generated parser passes a hook from inside its parse.
461	   461	    unsafe fn parser_mut<'a>(parser: *mut sys::llhttp__internal_t) -> Option<ParserMut<'a>> {
462	   462	        // SAFETY: the caller guarantees that `parser` is NULL or a live parser, exclusively
463	   463	        // held for the handle's lifetime, which is the export's call: each export makes its
464	   464	        // one operation with the handle and drops it before returning. Its `reason` is NULL or
465	   465	        // one of llhttp's literals, which live as long as the program. The hooks read and
466	   466	        // write only the parser's integers, never its `data` or `settings`, whose contracts
467	   467	        // are therefore not relied on.
