525	   525	    /// # Safety
526	   526	    ///
527	   527	    /// `parser` as `parser_mut` requires.
528	   528	    #[unsafe(no_mangle)]
529	   529	    unsafe extern "C" fn llhttp__after_message_complete(
530	   530	        parser: *mut sys::llhttp__internal_t,
531	   531	        _p: *const c_uchar,
532	   532	        _endp: *const c_uchar,
