184	    /// Whether another message may follow the one parsed on the same connection: an
185	    /// HTTP/1.1 one without `Connection: close`, or an earlier one with `Connection:
186	    /// keep-alive`, whose body does not end with the input
187	    /// ([`message_needs_eof`](Self::message_needs_eof)).
188	    ///
189	    /// The version is HTTP/1.1 or later only when its major and minor are both above zero, as
190	    /// llhttp reads it, so an `HTTP/2.0` message is read as an earlier one.
191	    ///
192	    /// ```
193	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
194	    ///
195	    /// let mut parser = Parser::new();
196	    /// parser.as_mut().init(ParserType::Response, None);
197	    /// parser
198	    ///     .as_mut()
199	    ///     .execute(b"HTTP/1.1 204 No Content\r\n\r\n")
200	    ///     .unwrap();
201	    /// assert!(parser.as_ref().should_keep_alive());
202	    ///
203	    /// parser.as_mut().init(ParserType::Response, None);
204	    /// parser
205	    ///     .as_mut()
206	    ///     .execute(b"HTTP/1.0 204 No Content\r\n\r\n")
207	    ///     .unwrap();
208	    /// assert!(!parser.as_ref().should_keep_alive());
209	    /// ```
210	    ///
211	    /// Replaces `fn::llhttp_should_keep_alive`
212	    #[doc(alias = "llhttp_should_keep_alive")]
213	    #[must_use]
214	    pub fn should_keep_alive(&self) -> bool {
215	        if self.http_major() > 0 && self.http_minor() > 0 {
216	            // HTTP/1.1.
217	            if self.flagged(sys::F_CONNECTION_CLOSE) {
218	                return false;
219	            }
220	        } else if !self.flagged(sys::F_CONNECTION_KEEP_ALIVE) {
221	            // HTTP/1.0 or earlier.
222	            return false;
223	        }
224	        !self.message_needs_eof()
225	    }
