307	    /// Sets whether the message upgrades the connection, [`upgrade`](ParserRef::upgrade),
308	    /// as llhttp's generated parser asks once the headers are read and before
309	    /// `on_headers_complete` runs, so that the callback sees it. A message with both
310	    /// `Upgrade` and `Connection: upgrade` upgrades when it is a request, or a `101
311	    /// Switching Protocols` response: for any other response the headers only announce
312	    /// support. Any other message upgrades when it is a `CONNECT` request.
313	    ///
314	    /// ```
315	    /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Parser, ParserType};
316	    ///
317	    /// let mut parser = Parser::new();
318	    /// parser.as_mut().init(ParserType::Response, None);
319	    /// parser
320	    ///     .as_mut()
321	    ///     .execute(b"HTTP/1.1 200 OK\r\nConnection: upgrade\r\nUpgrade: h2c\r\n\r\n")
322	    ///     .unwrap();
323	    /// assert!(!parser.as_ref().upgrade());
324	    /// parser.as_mut().set_upgrade(true);
325	    /// parser.as_mut().before_headers_complete();
326	    /// assert!(!parser.as_ref().upgrade());
327	    /// ```
328	    ///
329	    /// Replaces `fn::llhttp__before_headers_complete`
330	    #[doc(alias = "llhttp__before_headers_complete")]
331	    pub fn before_headers_complete(&mut self) {
332	        let upgrade = {
333	            let parser = self.as_ref();
334	            if parser.flagged(sys::F_UPGRADE) && parser.flagged(sys::F_CONNECTION_UPGRADE) {
335	                parser.is_request() || parser.status_code() == 101
336	            } else {
337	                parser.method() == Ok(Method::Connect)
338	            }
339	        };
340	        self.set_upgrade(upgrade);
341	    }
