588	        /// A zeroed parser of `parser_type` with `flags` and `upgrade` set.
589	        fn parser(parser_type: ParserType, flags: u32, upgrade: bool) -> Parser {
590	            let mut parser = Parser::zeroed();
591	            let mut handle = parser.as_mut();
592	            handle.set_parser_type(parser_type);
593	            handle.set_flags_raw(u16::try_from(flags).unwrap());
594	            handle.set_upgrade(upgrade);
595	            parser
596	        }
597	
598	        /// Calls `hook` with `parser` as `llhttp.c` does, its `p` and `endp` dangling, since
599	        /// the hooks never read them.
600	        fn call(
601	            hook: unsafe extern "C" fn(*mut sys::llhttp__internal_t, *const u8, *const u8) -> c_int,
602	            parser: &mut Parser,
603	        ) -> c_int {
604	            let p = ptr::dangling::<u8>();
605	            // SAFETY: the handle addresses a live parser, which nothing else accesses during
606	            // the call, and whose `reason` is NULL; the hooks never read `p` and `endp`.
607	            unsafe { hook(parser.as_mut().as_mut_ptr(), p, p) }
608	        }
