610	        #[test]
611	        fn before_headers_complete_sets_upgrade_and_returns_0() {
612	            let both = sys::F_UPGRADE | sys::F_CONNECTION_UPGRADE;
613	            let mut request = parser(ParserType::Request, both, false);
614	            assert_eq!(call(llhttp__before_headers_complete, &mut request), 0);
615	            assert!(request.as_ref().upgrade());
616	            let mut response = parser(ParserType::Response, both, true);
617	            assert_eq!(call(llhttp__before_headers_complete, &mut response), 0);
618	            assert!(!response.as_ref().upgrade());
619	        }
