624	                (ParserType::Request, 0, false, 0),
625	                (ParserType::Request, 0, true, 1),
626	                (ParserType::Request, sys::F_CHUNKED, false, 2),
627	                (ParserType::Response, 0, false, 4),
628	                (ParserType::Request, sys::F_TRANSFER_ENCODING, false, 5),
629	            ];
