        ///
        /// ```
        /// use libgit2_crustify::libgit2::deps::llhttp::llhttp::{Errno, Parsed, Parser, ParserType};
        ///
        /// let mut parser = Parser::new();
        /// assert_eq!(parser.as_ref().parser_type(), Ok(ParserType::Both));
        /// assert_eq!(parser.as_ref().error(), Ok(Errno::Ok));
