        #[must_use]
        pub fn new() -> Self {
            let mut parser = <Self as CZeroable>::zeroed();
            init(parser.as_mut().as_mut_ptr());
            parser
        }
    }

    impl Default for Parser {
        /// [`Parser::new`].
        fn default() -> Self {
            Self::new()
        }
    }

    /// Runs `llhttp__internal_init` on the parser `parser` addresses.
