use std::ffi::c_int;
use std::sync::LazyLock;

use ffibox::CZeroable;
use libgit2_crustify::libgit2::deps::llhttp::api::Settings;
use libgit2_crustify::libgit2::deps::llhttp::llhttp::{
    Callback, EventHandler, Parser, ParserMut, ParserType,
